// Command genkeycodes generates services' keyboard_key.g.go and
// keyboard_maps.g.go from Flutter's generated Dart files
// (packages/flutter/lib/src/services/keyboard_key.g.dart and
// keyboard_maps.g.dart, themselves generated by dev/tools/gen_keycodes), so
// the Go constants and maps are exactly the pinned Flutter's.
//
//	go run ./src/cmd/genkeycodes -flutter ~/Projetos/jonathanperis/flutter
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

const header = "// Code generated by src/cmd/genkeycodes from %s (Flutter 3.50.1). DO NOT EDIT.\n\npackage services\n\n"

func main() {
	flutter := flag.String("flutter", os.ExpandEnv("$HOME/Projetos/jonathanperis/flutter"), "Flutter clone")
	out := flag.String("out", "packages/flutter/lib/src/services", "output directory")
	flag.Parse()
	dir := filepath.Join(*flutter, "packages/flutter/lib/src/services")
	keySrc := read(filepath.Join(dir, "keyboard_key.g.dart"))
	mapSrc := read(filepath.Join(dir, "keyboard_maps.g.dart"))
	write(filepath.Join(*out, "keyboard_key.g.go"), genKeys(keySrc))
	write(filepath.Join(*out, "keyboard_maps.g.go"), genMaps(mapSrc))
}

func read(p string) string {
	b, err := os.ReadFile(p)
	if err != nil {
		log.Fatal(err)
	}
	return string(b)
}

func write(p string, src []byte) {
	formatted, err := format.Source(src)
	if err != nil {
		os.WriteFile(p+".broken", src, 0o644)
		log.Fatalf("%s: %v", p, err)
	}
	if err := os.WriteFile(p, formatted, 0o644); err != nil {
		log.Fatal(err)
	}
}

// goName is the Go name of a Dart static member of a key class.
func goName(class, member string) string {
	return class + strings.ToUpper(member[:1]) + member[1:]
}

// section returns the text of src from the line containing start up to the
// next line equal to end (exclusive).
func section(src, start, end string) string {
	i := strings.Index(src, start)
	if i < 0 {
		log.Fatalf("missing %q", start)
	}
	rest := src[i:]
	j := strings.Index(rest, end)
	if j < 0 {
		log.Fatalf("unterminated %q", start)
	}
	return rest[:j]
}

var (
	reConst  = regexp.MustCompile(`(?m)((?:^  ///.*\n)*)^  static const (Logical|Physical)KeyboardKey (\w+) = (?:Logical|Physical)KeyboardKey\((0x[0-9a-fA-F]+)\);`)
	reIntRef = regexp.MustCompile(`(?m)^\s*(0x[0-9a-fA-F]+): (\w+),`)
	reLabel  = regexp.MustCompile(`(?m)^\s*(0x[0-9a-fA-F]+): '([^']*)',`)
	reSyn    = regexp.MustCompile(`(?m)^\s*(\w+): <LogicalKeyboardKey>\{([^}]*)\},`)
)

func docLines(doc string) string {
	var b strings.Builder
	for _, l := range strings.Split(strings.TrimRight(doc, "\n"), "\n") {
		l = strings.TrimSpace(l)
		if l == "" {
			continue
		}
		b.WriteString("//" + strings.TrimPrefix(l, "///") + "\n")
	}
	return b.String()
}

func genKeys(src string) []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, header, "keyboard_key.g.dart")
	logical := section(src, "class LogicalKeyboardKey extends KeyboardKey", "\n}\n")
	physical := section(src, "class PhysicalKeyboardKey extends KeyboardKey", "\n}\n")
	for _, part := range []struct {
		class, src string
	}{{"LogicalKeyboardKey", logical}, {"PhysicalKeyboardKey", physical}} {
		b.WriteString("// Key constants (static const " + part.class + "s).\nvar (\n")
		for _, m := range reConst.FindAllStringSubmatch(part.src, -1) {
			b.WriteString(docLines(m[1]))
			fmt.Fprintf(&b, "\t%s = %s{%s}\n\n", goName(part.class, m[3]), part.class, m[4])
		}
		b.WriteString(")\n\n")
	}
	// The known keys, in the Dart maps' order.
	known := func(class, field, start string) {
		sec := section(src, start, "};")
		fmt.Fprintf(&b, "// %s are the keys of %s's _known map, in its order.\nvar %s = []%s{\n", field, class, field, class)
		for _, m := range reIntRef.FindAllStringSubmatch(sec, -1) {
			fmt.Fprintf(&b, "\t%s,\n", goName(class, m[2]))
		}
		b.WriteString("}\n\n")
	}
	known("LogicalKeyboardKey", "knownLogicalKeysList", "static const Map<int, LogicalKeyboardKey> _knownLogicalKeys")
	known("PhysicalKeyboardKey", "knownPhysicalKeysList", "static const Map<int, PhysicalKeyboardKey> _knownPhysicalKeys")
	syn := func(field, start string) {
		sec := section(src, start, "};")
		fmt.Fprintf(&b, "var %s = []keySynonyms{\n", field)
		for _, m := range reSyn.FindAllStringSubmatch(sec, -1) {
			var vals []string
			for _, v := range strings.Split(m[2], ",") {
				if v = strings.TrimSpace(v); v != "" {
					vals = append(vals, goName("LogicalKeyboardKey", v))
				}
			}
			fmt.Fprintf(&b, "\t{%s, []LogicalKeyboardKey{%s}},\n", goName("LogicalKeyboardKey", m[1]), strings.Join(vals, ", "))
		}
		b.WriteString("}\n\n")
	}
	syn("logicalKeySynonyms", "static final Map<LogicalKeyboardKey, Set<LogicalKeyboardKey>> _synonyms")
	syn("logicalKeyReverseSynonyms", "static final Map<LogicalKeyboardKey, Set<LogicalKeyboardKey>> _reverseSynonyms")
	labels := func(field, start string) {
		sec := section(src, start, "};")
		fmt.Fprintf(&b, "var %s = map[int]string{\n", field)
		for _, m := range reLabel.FindAllStringSubmatch(sec, -1) {
			fmt.Fprintf(&b, "\t%s: %s,\n", m[1], strconv.Quote(m[2]))
		}
		b.WriteString("}\n\n")
	}
	labels("logicalKeyLabels", "static const Map<int, String> _keyLabels")
	labels("physicalKeyDebugNames", "static const Map<int, String> _debugNames")
	return b.Bytes()
}

var reMap = regexp.MustCompile(`(?m)((?:^///.*\n)*)^const Map<(int|String), (LogicalKeyboardKey|PhysicalKeyboardKey|List<LogicalKeyboardKey\?>)> (\w+) =[^{]*\{\n`)

func genMaps(src string) []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, header, "keyboard_maps.g.dart")
	for _, loc := range reMap.FindAllStringSubmatchIndex(src, -1) {
		doc := src[loc[2]:loc[3]]
		keyType, valType, name := src[loc[4]:loc[5]], src[loc[6]:loc[7]], src[loc[8]:loc[9]]
		body := src[loc[1]:]
		body = body[:strings.Index(body, "\n};")]
		entries := splitEntries(body)
		gk := "int"
		if keyType == "String" {
			gk = "string"
		}
		gv := valType
		if strings.HasPrefix(valType, "List") {
			gv = "[]*LogicalKeyboardKey"
		}
		goVar := "K" + name[1:]
		b.WriteString(docLines(doc))
		fmt.Fprintf(&b, "var %s = map[%s]%s{\n", goVar, gk, gv)
		var keys []string
		for _, e := range entries {
			k, v := splitKV(e)
			k = goLiteral(k)
			keys = append(keys, k)
			fmt.Fprintf(&b, "\t%s: %s,\n", k, goValue(v))
		}
		b.WriteString("}\n\n")
		fmt.Fprintf(&b, "// %sKeys is %s.keys: the keys of %s in Dart's iteration order.\n", goVar, name, goVar)
		fmt.Fprintf(&b, "var %sKeys = []%s{%s}\n\n", goVar, gk, strings.Join(keys, ", "))
	}
	return b.Bytes()
}

// splitEntries splits a Dart map literal's body at its top-level commas.
func splitEntries(body string) []string {
	var out []string
	depth, start := 0, 0
	inStr := false
	for i := 0; i < len(body); i++ {
		c := body[i]
		switch {
		case inStr:
			if c == '\\' {
				i++
			} else if c == '\'' {
				inStr = false
			}
		case c == '\'':
			inStr = true
		case c == '[':
			depth++
		case c == ']':
			depth--
		case c == ',' && depth == 0:
			out = append(out, strings.TrimSpace(body[start:i]))
			start = i + 1
		}
	}
	if s := strings.TrimSpace(body[start:]); s != "" {
		out = append(out, s)
	}
	return out
}

func splitKV(e string) (string, string) {
	if strings.HasPrefix(e, "'") {
		end := strings.Index(e[1:], "'") + 1
		return e[:end+1], strings.TrimSpace(strings.TrimPrefix(e[end+1:], ":"))
	}
	i := strings.Index(e, ":")
	return strings.TrimSpace(e[:i]), strings.TrimSpace(e[i+1:])
}

func goLiteral(k string) string {
	if strings.HasPrefix(k, "'") {
		return strconv.Quote(k[1 : len(k)-1])
	}
	return k
}

func goValue(v string) string {
	if strings.HasPrefix(v, "<LogicalKeyboardKey?>[") {
		inner := strings.TrimSuffix(strings.TrimPrefix(v, "<LogicalKeyboardKey?>["), "]")
		var items []string
		for _, it := range strings.Split(inner, ",") {
			it = strings.TrimSpace(it)
			switch {
			case it == "":
			case it == "null":
				items = append(items, "nil")
			default:
				items = append(items, "&"+goValue(it))
			}
		}
		return "[]*LogicalKeyboardKey{" + strings.Join(items, ", ") + "}"
	}
	class, member, ok := strings.Cut(v, ".")
	if !ok {
		log.Fatalf("unexpected value %q", v)
	}
	return goName(class, member)
}
